def vshiftN(a,b,maxd=40):
    pa=set((r,c) for r,l in enumerate(a) for c,ch in enumerate(l) if ch=='N')
    pb=set((r,c) for r,l in enumerate(b) for c,ch in enumerate(l) if ch=='N')
    best=[]
    for d in range(-maxd,maxd+1):
        inter=sum(1 for (r,c) in pa if (r+d,c) in pb)
        best.append((inter,d))
    best.sort(reverse=True)
    return best[:3], len(pa), len(pb)
